      parties: [a, b].sort(),
      contactState: 'none', // none|signal|analyzing|contacted
      firstContactTick: null,
      opinion: 0,
      trust: 10,
      threat: 0,
      borderTension: 0,
      tradeInterdependence: 0,
      grievances: 0,
      warWeariness: 0,
      intelConfidence: 0.2,
