__register("src/app/ViewRegistry.js", function (__exports, __require) {
/**
 * app/ViewRegistry.js — 页面注册表（任务书 2.1）
 * 每个视图：{ id, titleKey, mount(ctx), unmount() }；同一时间只激活一个主视图。
 */

const views = new Map();
let active = null;

function registerView(view) {
  if (views.has(view.id)) throw new Error(`视图重复注册: ${view.id}`);
  views.set(view.id, view);
}

function getView(id) {
  return views.get(id);
}

function allViews() {
  return [...views.values()];
}

/** 切换视图；返回新激活的视图对象（供 App 绑定快照推送） */
function activateView(id, ctx) {
  if (active && active.id === id) return active;
  if (active) {
    try {
      active.unmount();
    } catch (e) {
      console.error(`视图 ${active.id} 卸载异常`, e);
    }
  }
  active = views.get(id) || null;
  if (!active) throw new Error(`视图未注册: ${id}`);
  active.mount(ctx);
  return active;
}

function activeView() {
  return active;
}

Object.assign(__exports, { registerView, getView, allViews, activateView, activeView });

});
