      const led = snap.resources?.balances || {};
      bar.appendChild(resourceChip({ icon: '◈', label: L('ui.credits'), value: led.credits ?? 0 }));
      bar.appendChild(resourceChip({ icon: '✦', label: L('ui.influence'), value: led.influence ?? 0 }));
