__register("src/app/Router.js", function (__exports, __require) {
/**
 * app/Router.js — hash 路由（任务书 8.6：#/galaxy 形式，兼容 GitHub Pages 二级路径）
 */

const listeners = new Set();

function parseHash() {
  const h = location.hash.replace(/^#\/?/, '');
  if (!h) return { screen: 'menu', param: null };
  const parts = h.split('/');
  return { screen: parts[0], param: parts.slice(1).join('/') || null };
}

function navigate(screen, param = null) {
  const target = `#/${screen}${param ? '/' + param : ''}`;
  if (location.hash === target) {
    emitChange();
  } else {
    location.hash = target;
  }
}

function onRouteChange(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

function emitChange() {
  const route = parseHash();
  for (const fn of listeners) fn(route);
}

function initRouter() {
  window.addEventListener('hashchange', emitChange);
  return parseHash();
}

Object.assign(__exports, { parseHash, navigate, onRouteChange, emitChange, initRouter });

});
