__register("src/persistence/Database.js", function (__exports, __require) {
/**
 * persistence/Database.js — IndexedDB 封装（任务书 8.1）
 *
 * 单库两 store：saves（存档记录）与 meta（轻量索引）。
 * 所有写操作在事务内完成；不支持 IndexedDB 的环境（file:// 某些浏览器）
 * 退化为内存实现并给出警告（测试可用）。
 */

const DB_NAME = 'void-frontier';
const DB_VERSION = 1;
const STORE_SAVES = 'saves';
const STORE_META = 'meta';

let memoryMode = false;
const memory = { saves: new Map(), meta: new Map() };

function openDb() {
  return new Promise((resolve) => {
    // 三级降级：IndexedDB 打开失败（file:// 沙箱/隐私模式/安全策略）→
    // 不 reject，转入 localStorage/内存分层，绝不向外抛出异常
    try {
      if (typeof indexedDB === 'undefined') {
        memoryMode = true;
        resolve(null);
        return;
      }
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE_SAVES)) {
          db.createObjectStore(STORE_SAVES, { keyPath: 'slotId' });
        }
        if (!db.objectStoreNames.contains(STORE_META)) {
          db.createObjectStore(STORE_META, { keyPath: 'k' });
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => {
        memoryMode = true;
        resolve(null);
      };
      req.onblocked = () => {
        memoryMode = true;
        resolve(null);
      };
    } catch (e) {
      memoryMode = true;
      resolve(null);
    }
  });
}

let dbPromise = null;
function db() {
  if (!dbPromise) {
    dbPromise = openDb().catch(() => {
      memoryMode = true;
      return null;
    });
  }
  return dbPromise;
}

function tx(storeName, mode, fn) {
  return db().then((database) => {
    if (memoryMode || !database) return fn(null);
    return new Promise((resolve, reject) => {
      const t = database.transaction(storeName, mode);
      const store = t.objectStore(storeName);
      const result = fn(store);
      // 统一返回 reqValue 的 holder（调用方用 holder.__value 取值，防双重解包）
      t.oncomplete = () => resolve(result);
      t.onerror = () => reject(t.error);
      t.onabort = () => reject(t.error || new Error('事务中止'));
    });
  });
}

function reqValue(request) {
  const holder = { __value: undefined };
  request.onsuccess = () => {
    holder.__value = request.result;
  };
  return holder;
}

/** localStorage 第三层（仅 memoryMode 时启用；超限静默跳过） */
const LS_PREFIX = 'vf-save:';

function lsPut(record) {
  try {
    const text = JSON.stringify(record);
    if (text.length > 4 * 1024 * 1024) return; // 超出 localStorage 配额预算
    localStorage.setItem(LS_PREFIX + record.slotId, text);
  } catch { /* 隐私模式/配额：静默 */ }
}

function lsGet(slotId) {
  try {
    const text = localStorage.getItem(LS_PREFIX + slotId);
    return text ? JSON.parse(text) : null;
  } catch {
    return null;
  }
}

function lsList() {
  const out = [];
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(LS_PREFIX)) {
        try {
          out.push(JSON.parse(localStorage.getItem(k)));
        } catch { /* 忽略损坏条目 */ }
      }
    }
  } catch { /* ignore */ }
  return out;
}

function lsDelete(slotId) {
  try {
    localStorage.removeItem(LS_PREFIX + slotId);
  } catch { /* ignore */ }
}

const Database = {
  isMemoryMode() {
    return memoryMode;
  },
  /** 诊断探针（测试与诊断面板用） */
  __diag() {
    return { memoryMode, dbOpen: !!dbPromise };
  },

  /** 写入存档槽（整条记录覆盖）。IDB 不可用时写 localStorage + 内存 */
  async putSave(record) {
    if (memoryMode) {
      memory.saves.set(record.slotId, record);
      lsPut(record);
      return;
    }
    try {
      await tx(STORE_SAVES, 'readwrite', (store) => {
        store.put(record);
      });
    } catch (e) {
      // 运行时异常（SecurityError 等）→ 永久降级并补写低层
      memoryMode = true;
      memory.saves.set(record.slotId, record);
      lsPut(record);
    }
  },

  async getSave(slotId) {
    if (memoryMode) {
      return memory.saves.get(slotId) || lsGet(slotId);
    }
    try {
      const holder = await tx(STORE_SAVES, 'readonly', (store) => reqValue(store.get(slotId)));
      return holder?.__value ?? lsGet(slotId);
    } catch (e) {
      memoryMode = true;
      return memory.saves.get(slotId) || lsGet(slotId);
    }
  },

  async deleteSave(slotId) {
    memory.saves.delete(slotId);
    lsDelete(slotId);
    if (memoryMode) return;
    try {
      await tx(STORE_SAVES, 'readwrite', (store) => {
        store.delete(slotId);
      });
    } catch {
      memoryMode = true;
    }
  },

  async listSaves() {
    let idbList = [];
    if (!memoryMode) {
      try {
        const holder = await tx(STORE_SAVES, 'readonly', (store) => reqValue(store.getAll()));
        idbList = holder?.__value || [];
      } catch {
        memoryMode = true;
      }
    }
    const merged = new Map();
    for (const rec of [...lsList(), ...[...memory.saves.values()], ...idbList]) {
      if (rec && rec.slotId) merged.set(rec.slotId, rec);
    }
    return [...merged.values()].sort((a, b) => (b.savedAt || '').localeCompare(a.savedAt || ''));
  },

  async setMeta(k, v) {
    if (memoryMode) {
      memory.meta.set(k, v);
      return;
    }
    try {
      await tx(STORE_META, 'readwrite', (store) => {
        store.put({ k, v });
      });
    } catch {
      memoryMode = true;
      memory.meta.set(k, v);
    }
  },

  async getMeta(k) {
    if (memoryMode) return memory.meta.get(k) ?? null;
    try {
      const holder = await tx(STORE_META, 'readonly', (store) => reqValue(store.get(k)));
      return holder?.__value?.v ?? null;
    } catch {
      memoryMode = true;
      return memory.meta.get(k) ?? null;
    }
  },
};

Object.assign(__exports, { Database });

});
__register("src/simulation/SnapshotBuilder.js", function (__exports, __require) {
/**
 * simulation/SnapshotBuilder.js — 只读渲染快照（任务书 2.2）
 *
 * UI/渲染层只消费快照，绝不直接写世界状态。
 * 快照为纯数据，按需包含解释信息（任务书 6.4 计算来源）。
 */

const { dateStr: dateStr } = __require("src/core/clock.js");
const { sortedKeys: sortedKeys } = __require("src/core/math.js");
const { getRelation: getRelation } = __require("src/domain/diplomacy/war.js");

/** 构建全局快照（App 以 ~4Hz 刷新） */
function buildSnapshot(world) {
  const E = world.entities;
  const player = E.factions[world.playerFactionId];

  const snap = {
    tick: world.tick,
    date: dateStr(world.tick),
    paused: null, // App 填充
    speedIdx: null,
    player: player ? factionSummary(world, player) : null,
    factions: sortedKeys(E.factions).map((id) => factionSummary(world, E.factions[id])),
    systems: buildSystemsView(world),
    fleets: buildFleetsView(world),
    colonies: buildColoniesView(world),
    battles: Object.keys(world.battles.active).sort().map((id) => ({
      id,
      systemId: world.battles.active[id].systemId,
      time: world.battles.active[id].time,
    })),
    alerts: buildAlerts(world),
    logLines: buildLogLines(world),
    resources: player ? resourceSummary(world, player) : null,
    pendingEvent: world.narrative.pendingChoices?.[0] || null,
    victory: world.victory,
  };
  return snap;
}

function factionSummary(world, f) {
  const led = world.economy.ledgers[f.id];
  return {
    id: f.id,
    name: f.name,
    color: f.color,
    isPlayer: f.id === world.playerFactionId,
    personality: f.personality,
    credits: led?.balances?.credits ?? 0,
    influence: led?.balances?.influence ?? 0,
    contactState: null, // 对玩家视角在 UI 层按关系填充
  };
}

function buildSystemsView(world) {
  const E = world.entities;
  const out = [];
  for (const id of sortedKeys(E.systems)) {
    const s = E.systems[id];
    out.push({
      id,
      name: s.name,
      x: s.x,
      y: s.y,
      star: s.star,
      lanes: s.lanes,
      ownerFactionId: s.ownerFactionId,
      surveyedLevel: s.surveyedBy[world.playerFactionId] ?? 0,
      dangerRating: s.dangerRating,
      resourceRating: s.resourceRating,
      planetCount: s.planetIds.length,
      habitableCount: s.planetIds.filter((pid) => E.planets[pid].habitability >= 30).length,
      colonyCount: s.planetIds.filter((pid) => E.planets[pid].colonyId).length,
      hasAnomaly: (s.anomalyIds || []).length > 0,
      fleetIds: [], // 由 buildFleetsView 反查填充
      stationCount: (s.stationIds || []).length,
    });
  }
  // 舰队位置反查
  const idx = new Map(out.map((s) => [s.id, s]));
  for (const id of sortedKeys(E.fleets)) {
    const f = E.fleets[id];
    if (f.systemId && idx.has(f.systemId)) idx.get(f.systemId).fleetIds.push(id);
  }
  return out;
}

function buildFleetsView(world) {
  const E = world.entities;
  const out = [];
  for (const id of sortedKeys(E.fleets)) {
    const f = E.fleets[id];
    out.push({
      id,
      name: f.name,
      factionId: f.factionId,
      systemId: f.systemId,
      inTransit: !!f.transit,
      transitInfo: f.transit ? { dest: f.transit.path[f.transit.path.length - 1], eta: f.transit.legEta - f.transit.legProgress } : null,
      shipCount: (f.shipIds || []).length,
      status: f.status || 'idle',
      stance: f.stance || 'hold',
    });
  }
  return out;
}

function buildColoniesView(world) {
  const E = world.entities;
  const out = [];
  for (const id of sortedKeys(E.colonies)) {
    const c = E.colonies[id];
    const planet = E.planets[c.planetId];
    out.push({
      id,
      name: planet ? planet.name : id,
      planetId: c.planetId,
      systemId: planet?.systemId,
      factionId: c.factionId,
      population: c.population?.total ?? 0,
      stability: c.stability ?? 0,
      housing: c.housing ?? 0,
      buildingCount: (c.buildings || []).length,
    });
  }
  return out;
}

function buildAlerts(world) {
  // 从事件日志提取需要玩家注意的条目（最近 24 小时）
  const cut = world.tick - 24;
  const out = [];
  const cats = world.events.log || {};
  const alarmTypes = new Set([
    'BattleStarted', 'BattleEnded', 'FleetStranded', 'ColonyFamine', 'ColonyBlackout',
    'TreatyBreached', 'TreatyExpired', 'WarDeclared', 'AnomalyDetected', 'FirstContact',
    'CrisisPhase', 'ColonyLost', 'ShipDestroyed', 'TechCompleted',
  ]);
  for (const cat of sortedKeys(cats)) {
    for (const e of cats[cat]) {
      if (e.tick >= cut && alarmTypes.has(e.type)) {
        out.push({ tick: e.tick, type: e.type, payload: e.payload, category: cat });
      }
    }
  }
  out.sort((a, b) => b.tick - a.tick);
  return out.slice(0, 30);
}

function buildLogLines(world) {
  const out = [];
  const cats = world.events.log || {};
  for (const cat of sortedKeys(cats)) {
    for (const e of cats[cat]) out.push({ tick: e.tick, type: e.type, category: cat, payload: e.payload });
  }
  out.sort((a, b) => a.tick - b.tick || (a.type < b.type ? -1 : 1));
  return out.slice(-40);
}

function resourceSummary(world, faction) {
  const led = world.economy.ledgers[faction.id];
  if (!led) return null;
  return { balances: { ...led.balances } };
}

/** 玩家视角的外交关系快照 */
function diplomacySnapshot(world) {
  const out = [];
  const pid = world.playerFactionId;
  for (const otherId of sortedKeys(world.entities.factions)) {
    if (otherId === pid) continue;
    const rel = getRelation(world, pid, otherId);
    const known = rel.contactState !== 'none';
    out.push({
      factionId: otherId,
      name: world.entities.factions[otherId].name,
      color: world.entities.factions[otherId].color,
      known,
      contactState: known ? rel.contactState : 'none',
      opinion: known ? rel.opinion : null,
      trust: known ? rel.trust : null,
      threat: known ? rel.threat : null,
      borderTension: known ? rel.borderTension : null,
      treaties: known ? rel.treaties.slice() : [],
      atWar: !!rel.warId,
    });
  }
  return out;
}

Object.assign(__exports, { buildSnapshot, diplomacySnapshot });

});
__register("src/simulation/WorldSimulation.js", function (__exports, __require) {
/**
 * simulation/WorldSimulation.js — 统一世界推进器（任务书 1.5 / 4.10）
 *
 * 固定步长累加器模型：App 的渲染循环调用 advanceOneTick；
 * 模拟推进与渲染帧率完全解耦（CORE-04）。暂停即不调用本函数。
 *
 * tick 内顺序：
 *   1. 调度队列到期项
 *   2-N. 各领域每小时阶段（TickPipeline 注册序）
 *   日/月/年结（按 tick 边界）
 *   事件分发（drain → dispatch）
 *   廉价不变量检查
 */

const { runHourly: runHourly, runDaily: runDaily, runMonthly: runMonthly, runYearly: runYearly } = __require("src/simulation/TickPipeline.js");
const { runDue: runDue } = __require("src/core/scheduler.js");
const { drainQueue: drainQueue, dispatch: dispatch } = __require("src/core/eventBus.js");
const { isDayStart: isDayStart, isMonthStart: isMonthStart, isYearStart: isYearStart } = __require("src/core/clock.js");
const { checkQuickInvariants: checkQuickInvariants } = __require("src/core/invariant.js");

// 按依赖顺序导入各领域阶段模块（import 副作用注册阶段）
__require("src/simulation/HourlySystems.js");
__require("src/simulation/DailySystems.js");
__require("src/simulation/MonthlySystems.js");
__require("src/simulation/SeasonalSystems.js");

/** 推进一个战略 tick（1 游戏小时）。唯一的世界状态推进入口。 */
function advanceOneTick(world) {
  world.tick += 1;

  // 1. 到期调度项（延迟命令、事件回调等）
  runDue(world);

  // 2. 领域每小时阶段
  runHourly(world);

  // 3. 日/月/年结
  if (isDayStart(world.tick)) {
    runDaily(world);
    if (isMonthStart(world.tick)) {
      runMonthly(world);
      if (isYearStart(world.tick)) {
        runYearly(world);
      }
    }
  }

  // 4. 事件分发（本 tick 产生的领域事件交给监听器）
  const events = drainQueue(world);
  dispatch(world, events);

  // 5. 廉价不变量（违规即抛出 —— 禁止静默续跑）
  const problems = checkQuickInvariants(world);
  if (problems.length > 0) {
    throw new Error(`[tick ${world.tick}] 世界不变量失败: ${problems.slice(0, 3).join(' ; ')}`);
  }

  world.stats.ticksProcessed += 1;
}

/** 推进 N tick（测试与离线模拟用） */
function advanceTicks(world, n) {
  for (let i = 0; i < n; i++) advanceOneTick(world);
}

Object.assign(__exports, { advanceOneTick, advanceTicks });

});
