    diplomacy: { progress: Math.min(1, activeTreaties / 3) * (crisisResolved ? 1 : 0.8), done: false },
    economy: { progress: Math.min(1, (led?.balances?.credits || 0) / 50000) * 0.6 + Math.min(1, colonies / 8) * 0.4, done: false },
